import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../App.css";

const ViewListings = () => {
  const [listings, setListings] = useState([
    {
      id: 1,
      title: "Bench Press Set",
      price: 200,
      condition: "Good",
      image: "https://via.placeholder.com/300x200",
    },
    {
      id: 2,
      title: "Treadmill (Foldable)",
      price: 450,
      condition: "Like New",
      image: "https://via.placeholder.com/300x200",
    },
  ]);

  const handleDelete = (id) => {
    const confirmDelete = window.confirm("Are you sure you want to delete this listing?");
    if (confirmDelete) {
      setListings(listings.filter((item) => item.id !== id));
    }
  };

  const handleEdit = (id) => {
    alert("Edit page not set up yet — you can route to /edit-listing/" + id);
  };

  return (
    <div>
      <Navbar />
      <main className="view-listings-wrapper">
        <h2>Your Listings</h2>

        {listings.length === 0 ? (
          <p className="empty-list">You haven't posted any listings yet.</p>
        ) : (
          <div className="listings-grid">
            {listings.map((item) => (
              <div className="listing-card" key={item.id}>
                <img src={item.image} alt={item.title} />
                <h4>{item.title}</h4>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${item.price}</p>
                <div className="listing-actions">
                  <button onClick={() => handleEdit(item.id)} className="edit-btn">Edit</button>
                  <button onClick={() => handleDelete(item.id)} className="delete-btn">Delete</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default ViewListings;
